/**
 * Canonical site origin. Set NEXT_PUBLIC_SITE_URL (no trailing slash) when the
 * custom domain goes live; every canonical, OG URL and JSON-LD URL reads this.
 */
export const SITE_URL = (
  process.env.NEXT_PUBLIC_SITE_URL || "https://fitthefile.com"
).replace(/\/+$/, "");

export const SITE_NAME = "FitTheFile";

/** Absolute URL for a site path, e.g. absoluteUrl("/merge-pdf"). */
export function absoluteUrl(path = "/"): string {
  return `${SITE_URL}${path.startsWith("/") ? path : `/${path}`}`;
}

/**
 * Default share image (generated by src/app/opengraph-image.tsx). Next.js
 * shallow-merges metadata, so any segment that sets its own `openGraph`
 * drops the inherited image — spread this into every `openGraph` object.
 */
export const DEFAULT_OG_IMAGES = [
  {
    url: "/opengraph-image",
    width: 1200,
    height: 630,
    alt: "FitTheFile — Make any PDF or photo fit an upload limit",
  },
];
